import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { findUserHandler } from "../handlers/findUserHandler";
import type { ApiError } from "../runtime/client";
import type { FindUserQueryType } from "../types/FindUserQueryType";

type Data = Awaited<ReturnType<typeof findUserHandler>>;

export function useFindUser(
  userType: FindUserQueryType,
  value: string,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["findUser", userType, value],
    queryFn: () => findUserHandler(userType, value),
    ...options,
  });
}
